def xml_value(v):
    v = escape(v).replace("'", "\\'").replace('"', '\\"')
    if v.startswith(" ") or v.endswith(" "):
        v = v.replace(" ", "\\u0020", 1) if v.startswith(" ") else v
        if v.endswith(" "):
            v = v[:-1] + "\\u0020"
    return v

for i, lang in enumerate(LANGS):
    d = RES / ("values" if lang == "en" else f"values-{lang}")
    lines = ['<?xml version="1.0" encoding="utf-8"?>',
             '<!-- Sign-in and profile (ProfilePages.kt and friends), the iPhone\'s words. Generated by android/generate_profile_strings.py; edit the list there. -->',
             '<resources>']
    for k, vals in S.items():
        assert len(vals) == 8, k
        fmt = ' formatted="false"' if False else ''
        lines.append(f'    <string name="{k}">{xml_value(vals[i])}</string>')
    lines.append('</resources>')
    (d / "strings_profile.xml").write_text("\n".join(lines) + "\n", encoding="utf-8")
print(len(S), "strings x", len(LANGS))
